{
  "name": "Office Supply Request Process",
  "resources": [
    {
      "name": "Employee",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Supervisor",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Purchase Department",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "System",
      "capacity": 1,
      "resource_type": "system"
    }
  ],
  "events": [
    {
      "id": "e_start_emp",
      "name": "Office supply request needed",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "e_msg_sent_to_sup",
      "name": "Request submitted to supervisor",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Office Supply Request"
    },
    {
      "id": "e_msg_rec_sup",
      "name": "Request received by supervisor",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Office Supply Request"
    },
    {
      "id": "e_msg_change_to_emp",
      "name": "Change requested sent",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Change Request Notification"
    },
    {
      "id": "e_msg_rec_change",
      "name": "Change request received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Change Request Notification"
    },
    {
      "id": "e_end_emp_reviewed",
      "name": "Comments reviewed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "e_msg_app_to_purch",
      "name": "Approved request sent to purchase dept",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Approved Request"
    },
    {
      "id": "e_msg_rej_to_sys",
      "name": "Rejection sent to system",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Rejection Notice"
    },
    {
      "id": "e_msg_rec_purch",
      "name": "Approved request received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Approved Request"
    },
    {
      "id": "e_msg_po_to_sys",
      "name": "Vendor selected sent to system",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Vendor Confirmation"
    },
    {
      "id": "e_msg_rec_sys_events",
      "name": "System event trigger received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Process Notification Trigger"
    },
    {
      "id": "e_end_sys_proc",
      "name": "System notification process completed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "t_submit_req",
      "name": "Submit office supply request",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Employee",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": [
        "do_req"
      ]
    },
    {
      "id": "t_review_comments",
      "name": "Review comments for change request",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Employee",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "do_comments"
      ],
      "output_data_ids": []
    },
    {
      "id": "t_eval_req",
      "name": "Evaluate office supply request",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Supervisor",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "do_req"
      ],
      "output_data_ids": [
        "do_comments"
      ]
    },
    {
      "id": "t_make_quotations",
      "name": "Make quotations",
      "bpmn_type": "bpmn:Task",
      "resource_name": "Purchase Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "do_req"
      ],
      "output_data_ids": [
        "do_quotation"
      ]
    },
    {
      "id": "t_select_vendor",
      "name": "Select a vendor",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Purchase Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": true,
      "input_data_ids": [
        "do_quotation"
      ],
      "output_data_ids": [
        "do_vendor"
      ]
    },
    {
      "id": "t_check_vendor_validity",
      "name": "Check vendor validity in system",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "Purchase Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "do_vendor"
      ],
      "output_data_ids": []
    },
    {
      "id": "t_gen_send_po",
      "name": "Generate and send purchase order",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "do_vendor"
      ],
      "output_data_ids": [
        "do_po"
      ]
    },
    {
      "id": "t_wait_delivery_invoice",
      "name": "Wait for product delivery and invoice",
      "bpmn_type": "bpmn:Task",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "do_po"
      ],
      "output_data_ids": [
        "do_invoice"
      ]
    },
    {
      "id": "t_send_notification",
      "name": "Send notification to user with result",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": [
        "do_notification"
      ]
    }
  ],
  "gateways": [
    {
      "id": "g_sup_decision",
      "name": "Supervisor Decision?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_sup_to_app",
          "condition": "Approved"
        },
        {
          "flow_id": "sf_sup_to_change",
          "condition": "Ask for change"
        },
        {
          "flow_id": "sf_sup_to_rej",
          "condition": "Rejected"
        }
      ]
    },
    {
      "id": "g_vendor_valid",
      "name": "Is vendor valid?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_vendor_ok",
          "condition": "Yes"
        },
        {
          "flow_id": "sf_vendor_not_ok",
          "condition": "No"
        }
      ]
    }
  ],
  "sequence_flows": [
    {
      "id": "sf_emp_start",
      "source_id": "e_start_emp",
      "target_id": "t_submit_req",
      "condition_name": null
    },
    {
      "id": "sf_emp_submit_to_end",
      "source_id": "t_submit_req",
      "target_id": "e_msg_sent_to_sup",
      "condition_name": null
    },
    {
      "id": "sf_emp_rec_change",
      "source_id": "e_msg_rec_change",
      "target_id": "t_review_comments",
      "condition_name": null
    },
    {
      "id": "sf_emp_rev_end",
      "source_id": "t_review_comments",
      "target_id": "e_end_emp_reviewed",
      "condition_name": null
    },
    {
      "id": "sf_sup_rec",
      "source_id": "e_msg_rec_sup",
      "target_id": "t_eval_req",
      "condition_name": null
    },
    {
      "id": "sf_sup_eval_to_g",
      "source_id": "t_eval_req",
      "target_id": "g_sup_decision",
      "condition_name": null
    },
    {
      "id": "sf_sup_to_app",
      "source_id": "g_sup_decision",
      "target_id": "e_msg_app_to_purch",
      "condition_name": "Approved"
    },
    {
      "id": "sf_sup_to_change",
      "source_id": "g_sup_decision",
      "target_id": "e_msg_change_to_emp",
      "condition_name": "Ask for change"
    },
    {
      "id": "sf_sup_to_rej",
      "source_id": "g_sup_decision",
      "target_id": "e_msg_rej_to_sys",
      "condition_name": "Rejected"
    },
    {
      "id": "sf_purch_rec",
      "source_id": "e_msg_rec_purch",
      "target_id": "t_make_quotations",
      "condition_name": null
    },
    {
      "id": "sf_purch_quote_to_select",
      "source_id": "t_make_quotations",
      "target_id": "t_select_vendor",
      "condition_name": null
    },
    {
      "id": "sf_purch_select_to_check",
      "source_id": "t_select_vendor",
      "target_id": "t_check_vendor_validity",
      "condition_name": null
    },
    {
      "id": "sf_purch_check_to_g",
      "source_id": "t_check_vendor_validity",
      "target_id": "g_vendor_valid",
      "condition_name": null
    },
    {
      "id": "sf_vendor_ok",
      "source_id": "g_vendor_valid",
      "target_id": "e_msg_po_to_sys",
      "condition_name": "Yes"
    },
    {
      "id": "sf_vendor_not_ok",
      "source_id": "g_vendor_valid",
      "target_id": "t_select_vendor",
      "condition_name": "No"
    },
    {
      "id": "sf_sys_rec",
      "source_id": "e_msg_rec_sys_events",
      "target_id": "t_gen_send_po",
      "condition_name": null
    },
    {
      "id": "sf_sys_po_to_wait",
      "source_id": "t_gen_send_po",
      "target_id": "t_wait_delivery_invoice",
      "condition_name": null
    },
    {
      "id": "sf_sys_wait_to_notify",
      "source_id": "t_wait_delivery_invoice",
      "target_id": "t_send_notification",
      "condition_name": null
    },
    {
      "id": "sf_sys_notify_end",
      "source_id": "t_send_notification",
      "target_id": "e_end_sys_proc",
      "condition_name": null
    }
  ],
  "pools": [
    {
      "id": "pool_employee",
      "name": "Employee / Petitioner",
      "element_ids": [
        "e_start_emp",
        "t_submit_req",
        "e_msg_sent_to_sup",
        "e_msg_rec_change",
        "t_review_comments",
        "e_end_emp_reviewed"
      ]
    },
    {
      "id": "pool_supervisor",
      "name": "Immediate Supervisor",
      "element_ids": [
        "e_msg_rec_sup",
        "t_eval_req",
        "g_sup_decision",
        "e_msg_app_to_purch",
        "e_msg_change_to_emp",
        "e_msg_rej_to_sys"
      ]
    },
    {
      "id": "pool_purchase",
      "name": "Purchase Department",
      "element_ids": [
        "e_msg_rec_purch",
        "t_make_quotations",
        "t_select_vendor",
        "t_check_vendor_validity",
        "g_vendor_valid",
        "e_msg_po_to_sys"
      ]
    },
    {
      "id": "pool_system",
      "name": "System",
      "element_ids": [
        "e_msg_rec_sys_events",
        "t_gen_send_po",
        "t_wait_delivery_invoice",
        "t_send_notification",
        "e_end_sys_proc"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "mf_emp_to_sup",
      "source_id": "e_msg_sent_to_sup",
      "target_id": "e_msg_rec_sup",
      "name": "Office supply request submitted"
    },
    {
      "id": "mf_sup_to_emp_change",
      "source_id": "e_msg_change_to_emp",
      "target_id": "e_msg_rec_change",
      "name": "Change requested"
    },
    {
      "id": "mf_sup_to_purch",
      "source_id": "e_msg_app_to_purch",
      "target_id": "e_msg_rec_purch",
      "name": "Approved request"
    },
    {
      "id": "mf_sup_to_sys_rej",
      "source_id": "e_msg_rej_to_sys",
      "target_id": "e_msg_rec_sys_events",
      "name": "Rejection notification trigger"
    },
    {
      "id": "mf_purch_to_sys",
      "source_id": "e_msg_po_to_sys",
      "target_id": "e_msg_rec_sys_events",
      "name": "Vendor selection confirmation"
    }
  ],
  "data_objects": [
    {
      "id": "do_req",
      "name": "Office Supply Request Form"
    },
    {
      "id": "do_comments",
      "name": "Supervisor Change Comments"
    },
    {
      "id": "do_quotation",
      "name": "Vendor Quotations"
    },
    {
      "id": "do_vendor",
      "name": "Selected Vendor Record"
    },
    {
      "id": "do_po",
      "name": "Purchase Order"
    },
    {
      "id": "do_invoice",
      "name": "Product Invoice"
    },
    {
      "id": "do_notification",
      "name": "Result Notification Message"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
